import React from 'react';import {createRoot} from 'react-dom/client';import PayrollHolidayManager from '../../app/payroll-holiday-manager';import {defaultHolidayCalendar,normalizePayrollHolidays,type HolidayCalendar} from '../../app/payroll-holidays';
if(!['127.0.0.1','localhost'].includes(location.hostname))throw Error('Local fictional fixture only.');
const calendars=new Map<number,HolidayCalendar>(JSON.parse(localStorage.getItem('fictional-holiday-calendars')||'[]'));let allowed=true,conflict=false,fail=false;
window.fetch=async(input,options)=>{if(!String(input).startsWith('/api/payroll-holidays'))return Response.json({error:'Unexpected local fixture request'},{status:400});if(options?.method!=='POST'){const year=Number(new URL(String(input),location.origin).searchParams.get('year'));return Response.json({calendar:calendars.get(year)||defaultHolidayCalendar(year),canManage:allowed});}if(!allowed)return Response.json({error:'Administrator and payroll management access are required.'},{status:403});if(fail){fail=false;return Response.json({error:'Simulated unconfirmed save. Your edits remain here.'},{status:503});}const b=JSON.parse(String(options.body)),current=calendars.get(b.year)||defaultHolidayCalendar(b.year);if(conflict){conflict=false;calendars.set(b.year,{...current,version:current.version+1});return Response.json({error:'Another administrator changed this calendar. Your edits remain here.'},{status:409});}try{const holidays=normalizePayrollHolidays(b.holidays,b.year);if(b.version!==current.version)return Response.json({error:'Stale calendar version'},{status:409});const calendar={...current,holidays,version:b.version+1,configured:true,updatedBy:'Fictional Admin',updatedAt:new Date().toISOString()};calendars.set(b.year,calendar);localStorage.setItem('fictional-holiday-calendars',JSON.stringify([...calendars]));return Response.json({saved:true,calendar});}catch(e){return Response.json({error:String(e)},{status:400});}};
createRoot(document.getElementById('root')!).render(<><aside style={{padding:12,display:'flex',gap:8,flexWrap:'wrap'}}><strong>Fictional local verification · no real payroll</strong><button onClick={()=>{conflict=true;}}>Simulate competing save</button><button onClick={()=>{fail=true;}}>Simulate failed save</button><button onClick={()=>{allowed=false;}}>Simulate access removal</button></aside><main style={{maxWidth:1200,margin:'auto',padding:12,fontFamily:'Arial,sans-serif'}}><PayrollHolidayManager initialYear={2026}/></main></>);
